function inferContractorImportedJobType(summary){
  var text=String(summary||'').toUpperCase();
  if(/\bMAJOR SERVICE\b|\bFULL SERVICE\b/.test(text))return 'Major Service';
  if(/\bFULL SERVICE\b|\bMINOR SERVICE\b|\bOIL SERVICE\b/.test(text))return 'Full Service';
  if(/\b6\s*MONTH|\bSIX[- ]?MONTH|SAFETY CHECK/.test(text))return '6 Month Safety Check';
  if(/\bMOT\b/.test(text))return 'MOT';
  if(/DIAGNOSTIC|FAULT FIND|CODE READ|WARNING LIGHT/.test(text))return 'Diagnostics';
  if(/BRAKE PAD|BRAKE DISC|BRAKES|CALIPER/.test(text))return 'Brakes';
  if(/TYRE|PUNCTURE|WHEEL/.test(text))return 'Tyres';
  if(/CLUTCH/.test(text))return 'Clutch';
  if(/TIMING BELT|CAMBELT/.test(text))return 'Timing Belt';
  if(/\bSERVICE\b/.test(text))return 'Full Service';
  return '';
}
function normaliseContractorImportedJob(job){
  var j=Object.assign({},job||{});
  j.work_required=String(j.work_required||j.summary_of_work||'').trim();
  j.amount_quoted=Number(j.amount_quoted!=null?j.amount_quoted:(j.cost||0));
  j.job_type=j.job_type||inferContractorImportedJobType(j.work_required);
  j.booking_source=j.booking_source||'Contractor spreadsheet import';
  return j;
}
window.CONTRACTOR_2026_JOBS=(window.CONTRACTOR_2026_JOBS||[]).map(normaliseContractorImportedJob);
